      "mainEntity": [
        {
          "@type": "Question",
          "name": "What standards guide electronic recycling projects?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Project documentation may reference NIST 800-88, HIPAA-related handling requirements, ISO 27001 controls, or DoD 5220.22-M where appropriate. STS reviews project needs and provides records describing equipment handling, data treatment, and final disposition."
          }
        },
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS coordinates commercial pickup in Bakersfield and across Kern County, with broader service throughout the San Joaquin Valley and all 50 states. Coverage depends on equipment volume, site conditions, transportation planning, and the requested timeline."
          }
        },
        {
          "@type": "Question",
          "name": "Is pickup available at no cost?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Complimentary pickup is available for qualifying volumes. A project coordinator can review equipment type, approximate quantity, loading conditions, and access requirements before confirming logistics and scheduling."
          }
        },
        {
          "@type": "Question",
          "name": "What happens after equipment is collected?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Equipment is received, documented, and routed according to project requirements. Data-bearing devices may receive sanitization or hard drive destruction, while reusable components and recyclable materials move through appropriate disposition channels."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide audit documentation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS can provide asset lists, certificates, chain-of-custody records, and disposition reporting based on the project scope. Documentation needs are reviewed before pickup so the final records match internal accounting and compliance workflows."
          }
        },
        {
          "@type": "Question",
          "name": "How do I request a quote?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Call 844-699-2913 or email recycle@stsrecycle.com. Share the equipment categories, estimated volume, pickup city, and preferred timing so STS can recommend an appropriate next step."
          }
        }
